func (object *Account) Destroy() {
	runtime.SetFinalizer(object, nil)
	object.ffiObject.destroy()
}

type FfiConverterAccount struct{}

var FfiConverterAccountINSTANCE = FfiConverterAccount{}

func (c FfiConverterAccount) Lift(handle C.uint64_t) *Account {
	result := &Account{
		newFfiObject(
			handle,
			func(handle C.uint64_t, status *C.RustCallStatus) C.uint64_t {
				return C.uniffi_scaas_sdk_fn_clone_account(handle, status)
			},
			func(handle C.uint64_t, status *C.RustCallStatus) {
				C.uniffi_scaas_sdk_fn_free_account(handle, status)
			},
		),
	}
	runtime.SetFinalizer(result, (*Account).Destroy)
	return result
}

func (c FfiConverterAccount) Read(reader io.Reader) *Account {
	return c.Lift(C.uint64_t(readUint64(reader)))
}

func (c FfiConverterAccount) Lower(value *Account) C.uint64_t {
	// TODO: this is bad - all synchronization from ObjectRuntime.go is discarded here,
	// because the handle will be decremented immediately after this function returns,
	// and someone will be left holding onto a non-locked handle.
	handle := value.ffiObject.incrementPointer("*Account")
	defer value.ffiObject.decrementPointer()
	return handle
}

func (c FfiConverterAccount) Write(writer io.Writer, value *Account) {
	writeUint64(writer, uint64(c.Lower(value)))
}

func LiftFromExternalAccount(handle uint64) *Account {
	return FfiConverterAccountINSTANCE.Lift(C.uint64_t(handle))
}

func LowerToExternalAccount(value *Account) uint64 {
	return uint64(FfiConverterAccountINSTANCE.Lower(value))
}

type FfiDestroyerAccount struct{}

func (_ FfiDestroyerAccount) Destroy(value *Account) {
	value.Destroy()
}

