	FfiDestroyerGasRows{}.Destroy(r.Gas)
	FfiDestroyerSequenceString{}.Destroy(r.GasOptIn)
	FfiDestroyerOptionalUint64{}.Destroy(r.MaxValidSecs)
	FfiDestroyerSequenceEndpointConfig{}.Destroy(r.Verifiers)
	FfiDestroyerPolicy{}.Destroy(r.VerifierPolicy)
	FfiDestroyerSequenceListedDex{}.Destroy(r.Dexes)
