// An authenticator's failure; `Unexpected` is a foreign exception inside the app's implementation.
type AuthError struct {
	err error
}

// Convenience method to turn *AuthError into error
// Avoiding treating nil pointer as non nil error interface
func (err *AuthError) AsError() error {
	if err == nil {
		return nil
	} else {
		return err
	}
}

func (err AuthError) Error() string {
	return fmt.Sprintf("AuthError: %s", err.err.Error())
}

func (err AuthError) Unwrap() error {
	return err.err
}

// Err* are used for checking error type with `errors.Is`
var ErrAuthErrorRefused = fmt.Errorf("AuthErrorRefused")
var ErrAuthErrorCancelled = fmt.Errorf("AuthErrorCancelled")
var ErrAuthErrorUnavailable = fmt.Errorf("AuthErrorUnavailable")
var ErrAuthErrorUnexpected = fmt.Errorf("AuthErrorUnexpected")

// Variant structs
type AuthErrorRefused struct {
}

func NewAuthErrorRefused() *AuthError {
	return &AuthError{err: &AuthErrorRefused{}}
}

func (e AuthErrorRefused) destroy() {
}

func (err AuthErrorRefused) Error() string {
	return fmt.Sprint("Refused")
}

