// A slot's key: `KeyRef` without the slots of an `msig` (a slot's key is never one, spec §7).
type SlotKey interface {
	Destroy()
}
type SlotKeyUa struct {
	Seed    string
	Kind    uint16
	Account uint32
	Index   uint32
}

func (e SlotKeyUa) Destroy() {
	FfiDestroyerString{}.Destroy(e.Seed)
	FfiDestroyerUint16{}.Destroy(e.Kind)
	FfiDestroyerUint32{}.Destroy(e.Account)
	FfiDestroyerUint32{}.Destroy(e.Index)
}

type SlotKeyNative struct {
	Seed    string
	Network string
	Index   uint32
}

func (e SlotKeyNative) Destroy() {
	FfiDestroyerString{}.Destroy(e.Seed)
	FfiDestroyerString{}.Destroy(e.Network)
	FfiDestroyerUint32{}.Destroy(e.Index)
}

type SlotKeyImported struct {
	Seed    string
	Network string
	Index   uint32
}

func (e SlotKeyImported) Destroy() {
	FfiDestroyerString{}.Destroy(e.Seed)
	FfiDestroyerString{}.Destroy(e.Network)
	FfiDestroyerUint32{}.Destroy(e.Index)
}

type SlotKeyKey struct {
	Seed string
	Id   string
}

func (e SlotKeyKey) Destroy() {
	FfiDestroyerString{}.Destroy(e.Seed)
	FfiDestroyerString{}.Destroy(e.Id)
}

// refused at signing (`Argument`)
type SlotKeyMsig struct {
	Ua string
}

func (e SlotKeyMsig) Destroy() {
	FfiDestroyerString{}.Destroy(e.Ua)
}

// a `bls12381-multi` group's member key (as `KeyRef::BlsMulti`)
type SlotKeyBlsMulti struct {
	Seed    string
	Account uint32
	Index   uint32
	KeyData string
}

func (e SlotKeyBlsMulti) Destroy() {
	FfiDestroyerString{}.Destroy(e.Seed)
	FfiDestroyerUint32{}.Destroy(e.Account)
	FfiDestroyerUint32{}.Destroy(e.Index)
	FfiDestroyerString{}.Destroy(e.KeyData)
}

// another party's signer (as `KeyRef::Signed`, a hand-off): never a slot's key, refused at signing
type SlotKeySigned struct {
	Signer string
}

func (e SlotKeySigned) Destroy() {
	FfiDestroyerString{}.Destroy(e.Signer)
}

type FfiConverterSlotKey struct{}

var FfiConverterSlotKeyINSTANCE = FfiConverterSlotKey{}

func (c FfiConverterSlotKey) Lift(rb RustBufferI) SlotKey {
	return LiftFromRustBuffer[SlotKey](c, rb)
}

func (c FfiConverterSlotKey) Lower(value SlotKey) C.RustBuffer {
	return LowerIntoRustBuffer[SlotKey](c, value)
}

