// Where a reviewed value comes from (spec §13.1).
type Source uint

const (
	// a field of the signed struct (or committed to by it, as a pay's `PayMeta`), decoded
	SourceSigned Source = 1
	// what the request named and the signed struct holds only in encrypted form (a confidential amount, recipient)
	SourceRequest Source = 2
	// what the SDK chose or read: the contract, every token or market touched with its mark
	SourceDerived Source = 3
)

type FfiConverterSource struct{}

var FfiConverterSourceINSTANCE = FfiConverterSource{}

func (c FfiConverterSource) Lift(rb RustBufferI) Source {
	return LiftFromRustBuffer[Source](c, rb)
}

func (c FfiConverterSource) Lower(value Source) C.RustBuffer {
	return LowerIntoRustBuffer[Source](c, value)
}

func (c FfiConverterSource) LowerExternal(value Source) ExternalCRustBuffer {
	return RustBufferFromC(LowerIntoRustBuffer[Source](c, value))
}
func (FfiConverterSource) Read(reader io.Reader) Source {
	id := readInt32(reader)
	return Source(id)
}

func (FfiConverterSource) Write(writer io.Writer, value Source) {
	writeInt32(writer, int32(value))
}

type FfiDestroyerSource struct{}

func (_ FfiDestroyerSource) Destroy(value Source) {
}

// A store's failure; `Unexpected` is a foreign exception inside an app's implementation.
type StoreError struct {
	err error
}

// Convenience method to turn *StoreError into error
// Avoiding treating nil pointer as non nil error interface
func (err *StoreError) AsError() error {
	if err == nil {
		return nil
	} else {
		return err
	}
}

func (err StoreError) Error() string {
	return fmt.Sprintf("StoreError: %s", err.err.Error())
}

func (err StoreError) Unwrap() error {
	return err.err
}

// Err* are used for checking error type with `errors.Is`
