type FfiConverterStoreError struct{}

var FfiConverterStoreErrorINSTANCE = FfiConverterStoreError{}

func (c FfiConverterStoreError) Lift(eb RustBufferI) *StoreError {
	return LiftFromRustBuffer[*StoreError](c, eb)
}

func (c FfiConverterStoreError) Lower(value *StoreError) C.RustBuffer {
	return LowerIntoRustBuffer[*StoreError](c, value)
}

func (c FfiConverterStoreError) LowerExternal(value *StoreError) ExternalCRustBuffer {
	return RustBufferFromC(LowerIntoRustBuffer[*StoreError](c, value))
}

func (c FfiConverterStoreError) Read(reader io.Reader) *StoreError {
	errorID := readUint32(reader)

	switch errorID {
	case 1:
		return &StoreError{&StoreErrorConflict{}}
	case 2:
		return &StoreError{&StoreErrorIo{}}
	case 3:
		return &StoreError{&StoreErrorUnavailable{}}
	case 4:
		return &StoreError{&StoreErrorUnexpected{}}
	default:
		panic(fmt.Sprintf("Unknown error code %d in FfiConverterStoreError.Read()", errorID))
	}
}

func (c FfiConverterStoreError) Write(writer io.Writer, value *StoreError) {
	switch variantValue := value.err.(type) {
	case *StoreErrorConflict:
		writeInt32(writer, 1)
	case *StoreErrorIo:
		writeInt32(writer, 2)
	case *StoreErrorUnavailable:
		writeInt32(writer, 3)
	case *StoreErrorUnexpected:
		writeInt32(writer, 4)
	default:
		_ = variantValue
		panic(fmt.Sprintf("invalid error value `%v` in FfiConverterStoreError.Write", value))
	}
}

type FfiDestroyerStoreError struct{}

func (_ FfiDestroyerStoreError) Destroy(value *StoreError) {
	switch variantValue := value.err.(type) {
	case StoreErrorConflict:
		variantValue.destroy()
	case StoreErrorIo:
		variantValue.destroy()
	case StoreErrorUnavailable:
		variantValue.destroy()
	case StoreErrorUnexpected:
		variantValue.destroy()
	default:
		_ = variantValue
		panic(fmt.Sprintf("invalid error value `%v` in FfiDestroyerStoreError.Destroy", value))
	}
}

